def _parse_section_header(stripped: str, lineno: int) -> str:
    """Validate a ``[name]`` line and return the section name."""
    if not stripped.endswith("]"):
        if "]" in stripped:
            raise ParseError(lineno, "trailing characters after ']'")
        raise ParseError(lineno, "missing ']' in section header")
    inner = stripped[1:-1]
    if "]" in inner:
        raise ParseError(lineno, "trailing characters after ']'")
    name = inner.strip()
    if not name:
        raise ParseError(lineno, "empty section name")
    return name


def _parse_key_value(stripped: str, lineno: int) -> tuple[str, str]:
    """Split a ``key = value`` or ``key: value`` line."""
    positions = [stripped.find(char) for char in "=:" if char in stripped]
    if not positions:
        raise ParseError(lineno, "expected 'key = value' or 'key: value'")
    index = min(positions)
    key = stripped[:index].strip().lower()
    if not key:
        raise ParseError(lineno, "empty key")
    return key, stripped[index + 1 :].strip()


def _interpolate(sections: dict[str, dict[str, str]]) -> None:
    """Interpolate every value in *sections* in place."""
    resolved: dict[tuple[str, str], str] = {}

    def resolve(section: str, key: str, stack: tuple[tuple[str, str], ...]) -> str:
        ident = (section, key)
        if ident in resolved:
            return resolved[ident]
        if ident in stack:
            start = stack.index(ident)
            chain = stack[start:] + (ident,)
            description = " -> ".join(f"{sec}:{name}" for sec, name in chain)
            raise InterpolationError(f"interpolation cycle: {description}")

        values = sections.get(section)
        if values is None:
            raise InterpolationError(f"unknown section {section!r}")
        if key not in values:
            raise InterpolationError(f"unknown key {key!r} in section {section!r}")

        result = interpolate_value(values[key], section, stack + (ident,))
        resolved[ident] = result
        return result

    def interpolate_value(
        value: str, section: str, stack: tuple[tuple[str, str], ...]
    ) -> str:
        pieces: list[str] = []
        index = 0
        while index < len(value):
            char = value[index]
            if char != "$":
                pieces.append(char)
                index += 1
                continue
            following = value[index + 1 : index + 2]
            if following == "$":
                # Consume both characters so the emitted "$" is never
                # reconsidered for interpolation.
                pieces.append("$")
                index += 2
                continue
            if following == "{":
                end = value.find("}", index + 2)
                if end == -1:
                    # An unmatched "${" is just an ordinary "$".
                    pieces.append("$")
                    index += 1
                    continue
                reference = value[index + 2 : end]
                ref_section, ref_key = _parse_reference(reference)
                target = section if ref_section is None else ref_section
                pieces.append(resolve(target, ref_key, stack))
                index = end + 1
                continue
            pieces.append("$")
            index += 1
        return "".join(pieces)

    for section, values in sections.items():
        for key in values:
            values[key] = resolve(section, key, ())


def _parse_reference(reference: str) -> tuple[str | None, str]:
    """Split the text between ``${`` and ``}`` into section and key."""
    reference = reference.strip()
    if ":" in reference:
        section, _, key = reference.partition(":")
        return section.strip(), key.strip().lower()
    return None, reference.lower()


def parse(text: str) -> dict[str, dict[str, str]]:
    """Parse INI text."""
    sections: dict[str, dict[str, str]] = {}
    current_section: str | None = None
    last_key: str | None = None

    for lineno, raw_line in enumerate(text.splitlines(), 1):
        try:
            stripped = raw_line.strip()
            if not stripped:
                last_key = None
                continue
            if stripped[0] in "#;":
                last_key = None
                continue
            if (
                raw_line[:1].isspace()
                and current_section is not None
                and last_key is not None
            ):
                sections[current_section][last_key] += "\n" + stripped
                continue
            if stripped.startswith("["):
                current_section = _parse_section_header(stripped, lineno)
                last_key = None
                continue
            if current_section is None:
                raise ParseError(lineno, "key before any section")
            key, value = _parse_key_value(stripped, lineno)
            sections[current_section][key] = value
            last_key = key
        except ParseError:
            raise
        except Exception as exc:  # pragma: no cover - defensive
            raise ParseError(lineno, str(exc)) from exc

    _interpolate(sections)
    return sections
